<?php
namespace App\Domain\Articles; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\Article; use Illuminate\Support\Facades\Cache; use Throwable; final class ArticleViewData { public function published(string $slug):?array{try{$item=Article::publiclyVisible()->where('slug',$slug)->first();if(!$item){return null;}return Cache::remember('public.articles.v1.'.$item->id.'.'.ArticleCache::version($item->id),now()->addMinutes(15),fn()=>$this->transform($this->load($item),false));}catch(Throwable){return null;}} public function preview(Article $item):array{return $this->transform($this->load($item),true);} private function load(Article $item):Article{return $item->load(['category','relatedArticles'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedSolutions'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedProducts'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedIndustries'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedCapabilities'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedPages'=>fn($q)=>$q->publiclyVisible()->limit(6)]);} private function transform(Article $x,bool $preview):array{return ['title'=>$x->title,'slug'=>$x->slug,'eyebrow'=>$x->eyebrow,'excerpt'=>$x->excerpt,'body'=>$x->body,'image'=>PublicAssetPath::isSafe($x->featured_image_path)?$x->featured_image_path:null,'image_alt'=>$x->featured_image_alt,'author'=>$x->author_name,'reading_time'=>$x->reading_time_minutes,'date'=>($x->published_at?:$x->scheduled_for)?->toDateString(),'category'=>$x->category?->is_active?$x->category->name:null,'meta_title'=>$x->meta_title?:$x->title,'meta_description'=>$x->meta_description?:$x->excerpt,'canonical_url'=>$x->canonical_url,'og_title'=>$x->og_title,'og_description'=>$x->og_description,'og_image'=>PublicAssetPath::isSafe($x->og_image_path)?$x->og_image_path:null,'robots'=>$preview?'noindex, nofollow':(($x->robots_index?'index':'noindex').', '.($x->robots_follow?'follow':'nofollow')),'related'=>$x->relatedArticles->map(fn($r)=>['title'=>$r->title,'url'=>route('insights.show',$r->slug)])->all()];} }
